<?php
require_once __DIR__.'/../auth_check.php';AccessManager::requirePageAccess();
if(!AccessManager::hasPermission('acces_admin')){http_response_code(403);exit('Accès réservé aux administrateurs.');}
require_once __DIR__.'/../services/RhFinancialWhatsAppMonitorFactory.php';
require_once __DIR__.'/../services/RhFinancialSchema.php';
$pdo=Database::getConnection();$userId=(int)($_SESSION['user_id']??0);$schemaReady=false;$monitor=null;$states=[];$history=[];$settings=[];$flash=(string)($_SESSION['rh_template_flash']??'');$error='';unset($_SESSION['rh_template_flash']);
$_SESSION['rh_template_monitor_csrf']??=bin2hex(random_bytes(32));$csrf=$_SESSION['rh_template_monitor_csrf'];
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$labels=['not_created'=>'À créer','creating'=>'Création en cours','creation_uncertain'=>'Création à vérifier','created'=>'Créé, à soumettre','pending'=>'En cours de validation','received'=>'Reçu par Meta','approved'=>'Approuvé','rejected'=>'Refusé','paused'=>'Suspendu','disabled'=>'Désactivé','unknown'=>'À contrôler'];
try{
    RhFinancialSchema::assertReady($pdo);$schemaReady=true;
    (new RhFinancialPointService($pdo))->actor($userId,'admin');$monitor=RhFinancialWhatsAppMonitorFactory::build($pdo);
    if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
        if(!hash_equals($csrf,(string)($_POST['_csrf']??'')))throw new DomainException('Session expirée. Rechargez la page.');
        $kind=(string)($_POST['kind']??'');
        switch($_POST['action']??''){
            case 'create_all':
            case 'create_two':
                $out=[];foreach(array_keys(RhFinancialPointPolicy::KINDS) as $k){try{$s=$monitor->poll($k,true);if(in_array($s['status'],['not_created','rejected','disabled'],true))$s=$monitor->create($k,$userId);$out[]=RhFinancialPointPolicy::KINDS[$k].' : '.($labels[$s['status']]??$s['status']).' · '.($s['sid']??'');}catch(Throwable $e){$out[]=RhFinancialPointPolicy::KINDS[$k].' : '.DailyPointWhatsAppTemplateService::safeDiagnostic($e->getMessage());}}$flash=implode(' | ',$out);break;
            case 'create':$monitor->create($kind,$userId);$flash='Modèle créé et soumis à Meta. Son statut sera suivi automatiquement.';break;
            case 'refresh':foreach(array_keys(RhFinancialPointPolicy::KINDS) as $k)$monitor->poll($k,true);$flash='Statuts contrôlés auprès de Twilio.';break;
            case 'automatic':$monitor->setAutomatic($kind,isset($_POST['enabled']),$userId);$monitor->poll($kind,true);$flash='Préférence enregistrée et statut contrôlé.';break;
            case 'attach':$monitor->attach($kind,trim((string)($_POST['sid']??'')),$userId);$monitor->poll($kind,true);$flash='Modèle existant rattaché et contrôlé.';break;
            case 'submit':$monitor->submitExisting($kind,$userId);$flash='Modèle existant soumis à Meta.';break;
            default:throw new DomainException('Action inconnue.');
        }
    }
    // Passive observations are throttled by persistent next_check and a database lock.
    foreach(array_keys(RhFinancialPointPolicy::KINDS) as $k){try{$states[$k]=$monitor->poll($k);}catch(Throwable $e){$states[$k]=$monitor->state($k);$states[$k]['error']=DailyPointWhatsAppTemplateService::safeDiagnostic($e->getMessage());}}
    $history=$monitor->history();$settings=(new RhFinancialPointService($pdo))->settings();
}catch(PDOException $e){error_log('RH templates: '.$e->getMessage());$error='Le suivi ne peut pas être chargé. Vérifiez l’installation RH et consultez le journal PHP.';}catch(Throwable $e){$error=DailyPointWhatsAppTemplateService::safeDiagnostic($e->getMessage());}
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$_SESSION['rh_template_flash']=$error?:$flash;header('Location: suivi_templates_whatsapp_rh.php');exit;}
$pageTitle='Suivi WhatsApp RH';$activeMenu='rh';require_once __DIR__.'/../decaissement/includes/header.php';require_once __DIR__.'/../decaissement/includes/navbar.php';
$csrfInput='<input type="hidden" name="_csrf" value="'.$h($csrf).'">';
?>
<link rel="stylesheet" href="../css/rh-financial.css?v=20261003-2">
<main class="rh-monitor"><section class="rh-hero"><p class="rh-eyebrow">FINEA · Ressources humaines</p><h1>WhatsApp · Validation des points RH</h1><p>Créez les modèles d’avances, de prêts et de salaires, suivez leur validation Meta et leur activation dans FINEA.</p><a class="rh-link" href="points_financiers_rh.php">Points financiers RH et compte DG</a><a class="rh-link" href="../admin/whatsapp_templates.php">Console WhatsApp centrale</a><a class="rh-link" href="../decaissement/test_whatsapp_point.php">Tester un modèle WhatsApp</a><a class="rh-link" href="../decaissement/parametres_signature_point_jour.php">Configuration Twilio</a>
<?php if($flash):?><p role="status" class="rh-warning"><?=$h($flash)?></p><?php endif?><?php if($error):?><p role="alert" class="rh-warning"><?=$h($error)?></p><?php endif?>
<?php if($states):?><form method="post"><?=$csrfInput?><input type="hidden" name="action" value="create_all"><button>Créer les modèles avances, prêts et salaires</button><small>Les modèles déjà suivis sont conservés.</small></form><form method="post"><?=$csrfInput?><input type="hidden" name="action" value="refresh"><button>Contrôler les statuts maintenant</button></form><?php endif?>
<p class="rh-monitor-note">Le contrôle automatique continue lorsque cet écran est fermé si le cron dédié est installé. La première activation fixe définitivement la date de démarrage du circuit ; les demandes antérieures conservent leur parcours historique.</p></section>
<?php if(!$schemaReady):?><section class="rh-install"><h2>Installation requise</h2><p>Exécutez cette commande dans le dossier de FINEA sur le serveur, puis rechargez la page :</p><code>php scripts/install_rh_financial.php</code></section><?php endif?>
<?php if($schemaReady):?><section class="rh-onboarding"><div class="rh-section-heading"><div><p class="rh-eyebrow">Mise en service</p><h2>Trois étapes pour envoyer les points au DG</h2></div></div><div class="rh-onboarding-grid"><article><span>01</span><b>Configurer le DG</b><p>Sélectionnez le signataire et enregistrez son numéro WhatsApp.</p><a href="points_financiers_rh.php#rh-dg">Ouvrir le paramétrage</a></article><article><span>02</span><b>Soumettre à Meta</b><p>Le bouton de création soumet les trois modèles avec la configuration Twilio de FINEA.</p></article><article><span>03</span><b>Activation automatique</b><p>Après approbation Utility, les invitations DG deviennent disponibles.</p></article></div></section><?php endif?>
<div class="rh-template-grid"><?php foreach($states as $kind=>$s):?><article class="rh-template"><p class="rh-eyebrow">Modèle de signature DG</p><h2><?=$h(RhFinancialPointPolicy::KINDS[$kind])?></h2><p class="rh-template-name"><small>Nom du modèle Twilio</small><strong><?=$h($s['name']??'À créer')?></strong></p><span class="rh-status rh-status-<?=$h($s['status'])?>"><?=$h($labels[$s['status']]??$s['status'])?></span><dl><dt>Content SID</dt><dd><?=$h($s['sid']?:'Aucun modèle créé')?></dd><dt>Nom du modèle</dt><dd><?=$h($s['name']??'—')?></dd><dt>Catégorie Meta</dt><dd><?=$h($s['category']??'—')?></dd><dt>Dernier contrôle</dt><dd><?=isset($s['last_checked'])?date('d/m/Y H:i:s',(int)$s['last_checked']):'Pas encore contrôlé'?></dd><dt>Prochain contrôle</dt><dd><?=!empty($s['next_check'])?date('d/m/Y H:i:s',(int)$s['next_check']):'Au prochain passage'?></dd><dt>Date de première activation</dt><dd><?=$h($settings[$kind.'_active_at']??'En attente')?></dd><dt>Modèle actif dans FINEA</dt><dd><?=$h($settings[$kind.'_sid']??'Aucun')?> </dd><dt>Utilisation du modèle suivi</dt><dd><?=!empty($settings[$kind.'_active_at'])&&($settings[$kind.'_sid']??'')===$s['sid']&&$s['status']==='approved'&&empty($s['error'])?'Modèle approuvé pour les invitations DG':'En attente ou indisponible'?></dd></dl>
<?php foreach(['reason'=>'Motif Meta','error'=>'Erreur de contrôle','activation_error'=>'Activation suspendue'] as $key=>$label):if(!empty($s[$key])):?><p class="rh-warning"><b><?=$label?> :</b> <?=$h($s[$key])?></p><?php endif;endforeach?>
<form method="post"><?=$csrfInput?><input type="hidden" name="action" value="automatic"><input type="hidden" name="kind" value="<?=$kind?>"><label><input type="checkbox" name="enabled" <?=!empty($s['auto_activate'])?'checked':''?>> Activer automatiquement après approbation Utility</label><button>Enregistrer</button></form>
<?php if(in_array($s['status'],['not_created','rejected','disabled'],true)):?><form method="post"><?=$csrfInput?><input type="hidden" name="action" value="create"><input type="hidden" name="kind" value="<?=$kind?>"><button><?=empty($s['sid'])?'Créer et soumettre à Meta':'Créer une nouvelle version'?></button></form><?php endif?>
<?php if($s['status']==='created'&&!empty($s['name'])):?><form method="post"><?=$csrfInput?><input type="hidden" name="action" value="submit"><input type="hidden" name="kind" value="<?=$kind?>"><button>Soumettre le modèle existant</button></form><?php endif?>
<?php if(in_array($s['status'],['creating','creation_uncertain'],true)):?><p class="rh-warning">Le résultat de la création doit être vérifié dans Twilio avec le nom ci-dessus. Rattachez son SID existant ; aucune recréation automatique n’est effectuée.</p><?php endif?>
<details><summary>Aperçu du message et rattachement d’un modèle existant</summary><p class="rh-preview"><?=$h(strtr(RhFinancialWhatsAppTemplateService::body($kind),array_combine(array_map(static fn($n)=>'{{'.$n.'}}',range(1,6)),array_slice(DailyPointWhatsAppTemplateService::samples(),0,6))))?></p><p><b>Bouton : Consulter et signer</b></p><form method="post"><?=$csrfInput?><input type="hidden" name="action" value="attach"><input type="hidden" name="kind" value="<?=$kind?>"><label>Content SID<input type="text" name="sid" pattern="HX[a-fA-F0-9]{32}" required placeholder="HX…"></label><button>Rattacher et contrôler</button></form></details></article><?php endforeach?></div>
<section style="margin-top:22px"><h2>Historique des contrôles et activations</h2><div style="overflow-x:auto"><table><thead><tr><th>Date serveur</th><th>Point / statut</th><th>Diagnostic</th></tr></thead><tbody><?php foreach($history as $e):?><tr><td><?=$h($e['created_at'])?></td><td><?=$h(RhFinancialPointPolicy::KINDS[$e['kind']])?><br><?=$h($labels[$e['status']]??$e['status'])?></td><td><?=$h($e['detail'])?><br><small><?=$h($e['sid'])?></small></td></tr><?php endforeach?><?php if(!$history):?><tr><td colspan="3">Aucun événement enregistré.</td></tr><?php endif?></tbody></table></div></section></main>
